int main() {
    int n;
    scanf("%d", &n);

    int lunch_ok = 0, lunch_total = 0;
    int dinner_ok = 0, dinner_total = 0;
    int midnight_ok = 0, midnight_total = 0;

    for (int i = 0; i < n; i++) {
        int hh, mm, duration;
        scanf("%d:%d %d", &hh, &mm, &duration);

        int ok = (duration <= 8) ? 1 : 0;

        // Categorize by hour
        if (hh >= 10 && hh <= 15) {
            lunch_total++;
            if (ok) lunch_ok++;
        } else if (hh >= 16 && hh <= 21) {
            dinner_total++;
            if (ok) dinner_ok++;
        } else {
            // midnight: 22-23, 0-9
            midnight_total++;
            if (ok) midnight_ok++;
        }
    }

    double lunch_pct = lunch_total > 0 ? (100.0 * lunch_ok / lunch_total) : 0.0;
    double dinner_pct = dinner_total > 0 ? (100.0 * dinner_ok / dinner_total) : 0.0;
    double midnight_pct = midnight_total > 0 ? (100.0 * midnight_ok / midnight_total) : 0.0;

    printf("Lunch: %.2f%%\n", lunch_pct);
    printf("Dinner: %.2f%%\n", dinner_pct);
    printf("Midnight: %.2f%%\n", midnight_pct);

    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int total[3] = {0, 0, 0}; // 0: lunch, 1: dinner, 2: midnight
    int ok[3] = {0, 0, 0};

    for (int i = 0; i < n; i++) {
        int h, m, t;
        if (scanf("%d:%d %d", &h, &m, &t) != 3) return 0;

        int slot = -1;
        if (h >= 6 && h < 15) slot = 0;       // lunch
        else if (h >= 15 && h < 21) slot = 1; // dinner
        else slot = 2;                        // midnight

        total[slot]++;
        if (t <= 8) ok[slot]++;
    }

    for (int i = 0; i < 3; i++) {
        if (total[i] == 0) {
            printf("0\n");
        } else {
            printf("%.10f\n", (double)ok[i] * 100.0 / total[i]);
        }
    }

    return 0;
}

