public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int lunchTotal = 0, lunchOk = 0;
        int dinnerTotal = 0, dinnerOk = 0;
        int midnightTotal = 0, midnightOk = 0;

        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split("\\s+");
            if (parts.length < 2) continue;

            String time = parts[0];
            int minutes = Integer.parseInt(parts[1]);

            String[] hm = time.split(":");
            int hour = Integer.parseInt(hm[0]);

            if (hour >= 6 && hour < 15) {
                lunchTotal++;
                if (minutes <= 8) lunchOk++;
            } else if (hour >= 15 && hour < 23) {
                dinnerTotal++;
                if (minutes <= 8) dinnerOk++;
            } else {
                midnightTotal++;
                if (minutes <= 8) midnightOk++;
            }
        }

        System.out.printf("lunch %.3f%%%n", percentage(lunchOk, lunchTotal));
        System.out.printf("dinner %.3f%%%n", percentage(dinnerOk, dinnerTotal));
        System.out.printf("midnight %.3f%%%n", percentage(midnightOk, midnightTotal));
    }

    private static double percentage(int ok, int total) {
        if (total == 0) return 0.0;
        return ok * 100.0 / total;
    }
}

